import { useCallback } from 'react'

/**
 * UI translations, keyed by the learner's *native* language.
 *
 * The catalogue is shared with the web app (`Linguispath-web/src/lib/i18n.js`)
 * and the two are deliberately the same shape — a flat `key: string` map per
 * language, with `{name}` placeholders — so a string written for one product
 * can be pasted into the other. Keys prefixed `m_` are mobile-only, for screens
 * and copy the web has no equivalent of.
 *
 * **Exercise content is never translated here.** Words, sentences and options
 * are authored once in the language being learned; only the instructions around
 * them are localised, and those come from the API's `exercise_instructions`
 * table rather than from this file. Translating the content would defeat the
 * exercise.
 *
 * Add a key to **all six languages** at once. A missing key falls back to
 * English rather than crashing, but a half-translated screen is worse than an
 * English one, so the parity check in the repo notes exists for a reason.
 */
