export function translate(code, key, params) {
  const template = STRINGS[code]?.[key] ?? STRINGS.en[key] ?? key
  if (!params) return template
  return template.replace(/\{(\w+)\}/g, (match, name) => (params[name] !== undefined ? params[name] : match))
}

/**
 * `t(key, params)` for the current learner.
 *
 * Falls back to English before the profile has loaded and for any language the
 * catalogue does not cover, so a screen is never blank while it waits.
 */
export function useTranslate() {
  const { user } = useAuth()
  const code = user?.nativeLanguage?.code ?? 'en'
  return useCallback((key, params) => translate(code, key, params), [code])
}

export function useLanguageCode() {
  const { user } = useAuth()
  return user?.nativeLanguage?.code ?? 'en'
}
